mapper.sql:
WHERE customers.is_active IN (1, 3) AND customers.id IN ( SELECT customer_companies.customer_id FROM customer_companies WHERE customer_companies.company_id IN ( SELECT user_companies.company_id FROM user_companies WHERE user_companies.user_id = #{userId} ) )
AND customers.created_by = #{userId}
AND customers.id = #{filter.customerId}
AND customers.id IN ( SELECT sale_target_employee_organizations.customer_id FROM sale_target_employee_organizations INNER JOIN sale_target_employees ON sale_target_employees.id = sale_target_employee_organizations.sale_target_employee_id INNER JOIN sale_targets ON sale_targets.id = sale_target_employees.sale_target_id WHERE sale_target_employees.employee_id = #{filter.saleTargetEmployeeId} AND sale_target_employees.is_active = 1 AND sale_target_employee_organizations.is_active = 1 AND sale_target_employees.sale_target_id = #{filter.saleTargetId} AND sale_targets.is_active = 1 )
AND ( customers.customer_code LIKE CONCAT("%", #{filter.searchText}, "%") OR customers.name LIKE CONCAT("%", #{filter.searchText}, "%") OR customers.main_number LIKE CONCAT("%", #{filter.searchText}, "%") OR payment_terms.name LIKE CONCAT("%", #{filter.searchText}, "%") OR EXISTS ( SELECT 1 FROM customer_contacts WHERE customer_contacts.customer_id = customers.id AND customer_contacts.contact_name LIKE CONCAT("%", #{filter.searchText}, "%") ) )

mapper.select:
SELECT



GROUP BY customers.id
ORDER BY


        ${filter.orderBy}


        customers.name DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.sql:
WHERE crm_activities_cards.is_active = 1 AND customer_contacts.is_active IN (1, 3) AND customers.is_active IN (1, 3) AND customers.id IN ( SELECT customer_companies.customer_id FROM customer_companies WHERE customer_companies.company_id IN ( SELECT user_companies.company_id FROM user_companies WHERE user_companies.user_id = #{userId} ) )
AND customers.id = #{filter.customerId}
AND DATE(crm_activities_cards.issue_date) >= #{filter.dateFrom}
AND DATE(crm_activities_cards.issue_date) <= #{filter.dateTo}
AND ( crm_activities_cards.issue_date LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_status.name LIKE CONCAT("%", #{filter.searchText}, "%") OR customer_contacts.contact_name LIKE CONCAT("%", #{filter.searchText}, "%") OR customers.name LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_cards.position LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_cards.subject LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_cards.result_action LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_cards.other LIKE CONCAT("%", #{filter.searchText}, "%") OR quotations.quotation_code LIKE CONCAT("%", #{filter.searchText}, "%") OR CASE WHEN crm_activities_cards.type = 0 THEN 'Issue' WHEN crm_activities_cards.type = 1 THEN 'Win' WHEN crm_activities_cards.type = 2 THEN 'Loss' ELSE '' END LIKE CONCAT("%", #{filter.searchText}, "%") )

mapper.select:
SELECT



GROUP BY crm_activities_cards.id
ORDER BY


        ${filter.orderBy}


        crm_activities_cards.issue_date DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.update:
UPDATE customer_contacts
SET position = #{position}
WHERE id = #{customerContactId}
AND is_active IN (1, 3)
